{
  "qid": "0002-01",
  "sample_id": "0002",
  "gen_prompt": "制作一张高分辨率的商业产品摄影图：画面中央突出展示三张不同的《最终幻想》集换式卡牌，三张卡牌整齐地呈扇形错落排列，卡牌正面朝向镜头并彼此部分遮挡，放置在干净的浅色平面上，背景简洁明亮，画面四周留出均匀边距。整体呈现真实的实体商品展示效果，卡面细节清晰可辨，避免电子游戏界面、普通周边或其他品牌元素。",
  "invocation": "L2",
  "knowledge_dim": "实体集换式卡牌的产品形态与IP识别",
  "fidelity_checks": [
    {
      "check": "画面主体应为最终幻想集换式卡牌的实体卡牌，而非电子游戏画面或普通周边。",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "[1]"
        ]
      },
      "rubric": {
        "tier_0": "完全没有可识别的实体卡牌，或主体仅为电子游戏画面、普通周边等不符合对象。",
        "tier_1": "能看出与该游戏相关的卡牌或商品，但实体卡牌属性不够明确，或同时混入了明显的电子游戏界面、普通周边元素。",
        "tier_2": "主体明确呈现真实的最终幻想集换式卡牌实体商品；本题选取的多张卡牌形态清楚，且没有以电子游戏画面或普通周边替代主体。"
      },
      "variants_used": "选取多张卡牌",
      "visibility_requirement": "至少应有两张卡牌的大部分正面可见并能判断为实体印刷品；若个别卡牌被遮挡，只要主体中仍有足够卡牌可判定实体形态，不因局部遮挡扣除此条。",
      "weight": 1.0
    },
    {
      "check": "露出的单卡应呈现标准的竖向矩形印刷卡牌形态。",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "[2]"
        ]
      },
      "rubric": {
        "tier_0": "露出的卡牌明显不是竖向矩形，例如呈横向卡、圆形、严重变形或无法辨认卡片轮廓。",
        "tier_1": "多数卡牌大致为竖向矩形，但有明显比例失真、边缘变形或个别卡牌形态不稳定。",
        "tier_2": "所有可见单卡均保持清楚、稳定的竖向矩形印刷卡牌轮廓；透视造成的轻微梯形变化不影响其竖向矩形卡牌属性。"
      },
      "variants_used": "无变体",
      "visibility_requirement": "至少一张卡牌需有完整或接近完整的外轮廓；被其他卡牌遮挡的部分按可见轮廓判断，不要求每张卡牌四角全部露出。",
      "weight": 1.0
    },
    {
      "check": "卡面插画内容应来自最终幻想系列自身的IP范围。",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "[3]"
        ]
      },
      "rubric": {
        "tier_0": "卡面没有可识别的最终幻想系列内容，或主要插画明显属于无关原创题材。",
        "tier_1": "部分卡面呈现疑似最终幻想风格或相关元素，但系列归属模糊，或只有少量卡面符合。",
        "tier_2": "所有主要可见卡面均呈现最终幻想系列自身的角色、召唤兽、怪物、经典场景、系列属性符号、陆行鸟或莫古利等内容；允许这些合法主题在不同卡牌间自由组合。"
      },
      "variants_used": "覆盖系列历代角色、召唤兽、怪物、经典场景、元素水晶/属性符号、陆行鸟/莫古利中的任意合法主题组合",
      "visibility_requirement": "至少两张卡牌的主要插画区域需清晰可见；若某张卡被遮挡，只按其可见的主要插画区域判定，不要求每张卡完整展示。",
      "weight": 1.0
    },
    {
      "check": "正面露出的卡牌应具有集换式卡牌所需的游戏信息要素。",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "[4]"
        ]
      },
      "rubric": {
        "tier_0": "正面卡牌完全没有卡名、元素水晶图标、费用或数值属性标识、卡牌类型、效果文本等游戏信息，或只是一张无信息的插画海报。",
        "tier_1": "部分正面卡牌出现少量游戏信息要素，但信息区域不完整、难以辨认，或不同卡面类型的版式表现混乱。",
        "tier_2": "正面可见的卡牌均保留与其版式相符的游戏信息区域；每张至少清楚呈现卡名、元素水晶图标、费用或数值等属性标识、卡牌类型、效果文本中的若干项。标准边框、全幅插画、闪卡或促销版式均可，只要信息要素与版式相符。"
      },
      "variants_used": "覆盖标准边框卡面、全幅插画卡面、闪卡或促销卡面中的任意合法版式",
      "visibility_requirement": "至少两张卡牌的正面信息区域需达到可判定程度；局部遮挡或透视缩小导致个别文字无法逐字阅读时，仍可依据信息栏结构、图标和数值区域判断，不要求文字完全可读。",
      "weight": 1.0
    },
    {
      "check": "卡牌或其可见包装区域应带有能够识别为Final Fantasy TCG的视觉标识。",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "[5]"
        ]
      },
      "rubric": {
        "tier_0": "画面中完全没有能够将对象识别为Final Fantasy TCG的标志或文字标识，且无法从可见设计建立该归属。",
        "tier_1": "出现模糊、残缺或疑似相关的标识，但文字或图形不足以稳定识别为Final Fantasy TCG。",
        "tier_2": "至少一张卡牌或可见商品区域清楚呈现与Final Fantasy TCG对应的官方视觉标识，例如“FINAL FANTASY TRADING CARD GAME”字样或等效的明确标志；标识可因透视而轻微缩小，但不能被主体遮住。"
      },
      "variants_used": "无变体",
      "visibility_requirement": "至少一处卡牌顶部、底部、背面或包装区域需清晰可见；若标识位于被遮挡区域，则应以其他可见卡牌或商品区域的标识判定。",
      "weight": 1.0
    },
    {
      "check": "所有可见卡面不得出现最终幻想系列以外的其他IP专属角色或怪物形象。",
      "anchor": {
        "type": "combination",
        "constraint_refs": [
          "[6]"
        ]
      },
      "rubric": {
        "tier_0": "任一主要可见卡面出现其他知名IP专属角色或怪物，或画面明显混入宝可梦、游戏王等其他卡牌游戏的专属形象。",
        "tier_1": "没有明显的其他IP主体，但局部出现疑似跨IP的角色、怪物或难以归属的强烈相似形象。",
        "tier_2": "所有可见卡面的人物、召唤兽、怪物与其他插画主体均属于最终幻想系列或无专属IP属性的通用装饰，不出现其他IP专属角色或怪物。"
      },
      "variants_used": "无变体",
      "visibility_requirement": "按主要可见插画区域判断；被遮挡或过小而无法辨认的局部不作推断，至少两张卡牌的主要画面需达到可判定程度。",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "画面中展示三张不同的最终幻想集换式卡牌。",
      "facet": "quantity",
      "rubric": {
        "tier_0": "没有卡牌，或可辨认的卡牌数量明显不是三张。",
        "tier_1": "大致呈现三张卡牌，但有一张严重缺失、重复融合或数量因遮挡难以确认。",
        "tier_2": "清楚呈现恰好三张彼此独立、可区分的卡牌。"
      }
    },
    {
      "check": "三张卡牌整齐地呈扇形错落排列，并彼此部分遮挡。",
      "facet": "spatial_2d",
      "rubric": {
        "tier_0": "卡牌没有形成扇形错落关系，或排列方向与位置关系完全不符。",
        "tier_1": "卡牌大致有错落或扇形趋势，但排列松散、遮挡关系不清或位置关系部分错误。",
        "tier_2": "三张卡牌在画面中央形成明确的扇形错落布局，彼此存在自然的部分遮挡，整体位置关系清楚。"
      }
    },
    {
      "check": "三张卡牌正面朝向镜头，并作为画面中央的主要视觉焦点。",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "卡牌背面朝向镜头、无法辨认正面，或卡牌被背景和其他物体压过而不再是主体。",
        "tier_1": "卡牌基本朝向镜头且位于中心，但部分严重偏转、过小或焦点不够突出。",
        "tier_2": "三张卡牌均以正面为主要可见面朝向镜头，并在中央占据主要视觉面积与焦点；透视造成的轻微角度差异不影响正面识别。"
      }
    }
  ],
  "quality_facets": [
    "physical_logic",
    "material_texture",
    "edge_clarity",
    "resolution"
  ],
  "aesthetic_facets": [
    "composition",
    "color_harmony",
    "anatomical_fidelity"
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "[1]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[2]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[3]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[4]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[5]",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "[6]",
        "题面中是否出现": "无"
      }
    ],
    "结论": "全为无"
  },
  "notes": "题面仅规定了主体数量、排列、朝向、展示场景与画面呈现方式；不得依据样本图的具体角色、颜色、纹样或文字内容追加保真度要求。"
}
